<script>
import draggable        from 'vuedraggable'

import jdb              from '../../jdb-tools.js'
import flexyState       from '../../flexy-state.js'
import flexyButton      from '../flexy-button.vue'

import FlexyPagination  from '../flexy-pagination.vue'
import FlexyGridCell    from './flexy-grid-cell.vue'
// import FlexyForm        from './../form/flexy-form.vue' // https://vuejs.org/v2/guide/components.html#Circular-References-Between-Components

export default {
  name: 'FlexyGrid',
  components: {draggable,flexyButton,FlexyGridCell,FlexyPagination },
  props:{
    'name':String,
    'title':{
      type: String,
      default:'',
    },
    'api':{
      type: [String,Boolean],
      default:false,
    },
    'order': {
      type   :String,
      default:''
    },
    'offset': {
      type   :String,
      default:'0'
    },
    'limit': {
      type   :String,
      default:''
    },
    'filter':{
      type   :[String,Object],
      default:'',
    },
    'type':{
      type:String,
      default:'table',
    },
    'selection':{
      type:[Array,Boolean],
      default:false,
    },
    'multiple':{
      type:Boolean,
      default:true,
    },
    'autoresize': {
      type:Boolean,
      default:false,
    },
  },
  
  // https://vuejs.org/v2/guide/components.html#Circular-References-Between-Components
  beforeCreate: function () {
    this.$options.components.FlexyForm = require('./../form/flexy-form.vue');
  },

  created : function() {
    flexyState.eventbus.$on('upload-file', this.dropUploadFiles);
  },
  
  
  mounted : function() {
    var self = this;
    self.setUrlOptions();
    self.calcLimit(); // -> NIET MEER, zodat pagination uit kan
    
    // Bij resize
    var resizeTimer;
    window.addEventListener('resize', function(event){
      clearTimeout(resizeTimer);
      resizeTimer = setTimeout(function() {
        if (self.calcLimit()) {
          self.reloadPageAfterResize();
        }
        else {
          if (self.pagination) {
            self.items.splice(self.apiParts.limit);
            self.dataInfo.limit = self.apiParts.limit;
            self.dataInfo.num_pages = Math.ceil(self.dataInfo.total_rows / self.dataInfo.limit);
          }
        }
      }, 250);
    });

    document.onmousemove = function(e){
      self.mouseY = e.pageY;
    }

    this.loadStart();
  },

  
  beforeUpdate : function() {
    // Test if (re)load needed
    if ( this.name!==this.currentName ) {
      this.loadStart(true);
    }
    this.currentName = this.name;

    //
    // Selection
    //
    if (this.selection) {
      // Pas selected aan
      var selected = [];
      for (var i = 0; i < this.selection.length; i++) {
        var src = this.selection[i];
        var key_item = false;
        for (var j = 0; j < this.items.length; j++) {
          var item = this.items[j];
          if (item['media_thumb'].value === src) {
            key_item = item['id'].value;
          }
        }
        if (key_item) selected.push(key_item);
      }
      
      if ( !_.isEqual(selected,this.selected) ) {
        this.selected = _.clone(selected);
      }
    }

  },

  data : function() {
    return {
      isLoading         : false,
      uiTitle           : this.title ? this.title : '',
      currentName       : '',
      items             : [],
      fields            : [],
      actions           : [],
      searchable_fields : [],
      dataInfo          : {},
      selected          : [],
      mediaSelection    : this.selection,
      pagination        : true,
      apiParts    : {
        order         : this.order,
        filter        : this.filter,
        offset        : 0,
        limit         : this.limit,
        txt_abstract  : true,
        as_grid       : true,
      },
      urlOptions      : {},
      changeUrlApi: true,
      focus       : {id:false,cell:false},
      draggable   : {
        item        : false,
        orderStart  : 0,
        oldItems    : false,
        children    : false,
        newPage     : false,
        oldIndex    : 0,
        newIndex    : 0,
      },
      findTerm            : this.filter,
      extendedFind        : true,
      extendedTermDefault : { field:'',term:'',and:'OR',equals:'exist' },
      extendedTerm        : [],
      oldExtendedTerm     : [],
      uploadFiles         : [],
      bulkuploadFiles     : [],
      dropUploadHover     : false,

      mouseY              : 0,
      mouseInterval       : null,
      dragPosition        : '',
    }
  },

  
  computed:{

    /**
     * Options for draggable
     */
    draggableOptions : function() {
      return {
        draggable     : 'tr',
        handle        : '.draggable-handle',
        forceFallback : true,
      }
    },
    
  },

  watch : {
    '$route.params.table' : function(val) {
      if (val !== this.currentName) {
        this.loadStart(true);
      }
    },
    '$route.params.path' : function(val) {
      if (val !== this.currentName) {
        this.loadStart(true);
      }
    }

  },

  
  methods:{

    reset : function() {
      this.currentName       = '';
      this.pagination        = true;
      this.fields            = [];
      this.searchable_fields = [];
      this.actions           = [];
      this.items             = [];
      this.dataInfo          = {};
      this.findTerm          = '';
      this.extendedFind      = false;
      this.selected          = [];
    },

    setUrlOptions : function() {
      var options = location.search;
      if (options!=='' && options.substr(0,9)==='?options=') {
        options = options.substr(9);
        options = decodeURIComponent(options);
        options = JSON.parse(options);
        this.urlOptions = Object.assign(this.urlOptions,options);
        this.apiParts = Object.assign(this.apiParts,this.urlOptions);
        this.findTerm = this.apiParts.filter;
      }
    },

    dataName : function() {
      var name = this.name;
      if (this.gridType()==='media') {
        name = 'media_'+name;
      }
      return name;
    },

    
    calcLimit : function( view ) {
      // console.log('calcLimit',this.pagination);
      if (!this.autoresize) return false;

      // Sizes:
      var padding   = 8;
      var rowHeight = 37;
      var thumb = { width: 264, height: 292 }
      var small = { width: 136, height: 164 }

      // Bepaal view
      if (_.isUndefined(view)) view = this.getMediaView();

      // Bepaal maximale breedte en hoogte
      var thisEl    = this.$el;
      var parentEl  = thisEl.parentElement;
      var max_width = thisEl.offsetWidth - (2*padding);
      if (parentEl) var max_width = parentEl.offsetWidth - (2*padding);
      var max_height  = window.innerHeight - (2*padding) - rowHeight;
      var header      = document.querySelector('#header');
      if (header!==null) max_height -= header.offsetHeight;
      var grid_header = document.querySelector('#content .card.grid>.card-header');
      if (grid_header!==null) max_height -= grid_header.offsetHeight;
      var grid_footer = document.querySelector('#content .card.grid>.card-footer');
      if (grid_footer!==null) max_height -= grid_footer.offsetHeight;

      // Bepaal breedte en hoogte
      var width  = max_width;
      var height = max_height;

      // Defaults:
      var rows = 1;
      var cols = 10;
      var new_limit = this.apiParts.limit;

      if (this.gridType()!=='media') view = 'list';
      switch (view) {

        case 'small':
          thumb = small;
          rows = 2;
        case 'thumbs':
          if (this.type!=='mediapicker') rows = Math.floor(height / thumb.height);
          cols = Math.floor(width / thumb.width);
          new_limit = (cols * rows) - 1;
          if (new_limit <= 1) {
            new_limit += cols ;
            rows++;
          }
          if (new_limit <= 1) new_limit = 1;
          break;

        case 'list':
        default:
          new_limit = 10;
          if (this.type!=='mediapicker') {
            if (this.gridType()==='media') height -= rowHeight; // Extra rij eraf voor upload item
            rows = height / rowHeight;
            var step = (rows <= 10)?2:5;
            new_limit = Math.floor(rows / step) * step;
          }
          if (new_limit <= 1) new_limit = 1;
      }
      
      var changed = false;
      // Calc new offset
      var new_offset = 0;
      if ( this.pagination ) {
        new_offset = this.apiParts.offset;
        if (this.apiParts.offset > 0) {
          this.apiParts.offset = Math.floor( this.apiParts.offset / this.apiParts.limit) * this.apiParts.limit
        }
        // Reload needed?
        changed = (new_limit > this.apiParts.limit || new_offset !== this.apiParts.offset);
      }
      if (new_limit<0) new_limit = 0;
      this.apiParts.limit = new_limit;
      this.apiParts.offset = new_offset;
      return changed;
    },

    loadStart : function(reset) {
      this.reset();
      if (!this.isLoading) {
        this.isLoading = true;
        var args = {
          offset : this.apiParts.offset,
          limit  : this.apiParts.limit,
          order  : this.apiParts.order,
          filter : this.apiParts.filter,
        };
        if (reset===true || this.type==='mediapicker') {
          args = {
            offset : 0,
            limit  : this.apiParts.limit,
            order  : '',
            filter : '',
          };
        }
        this.reloadPage(args);
      }

      // Init Find
      this.extendedFind = false;
      if (this.urlOptions.filter.substr(0,1)==='[' || this.urlOptions.filter.substr(0,1)==='{') {
        this.extendedFind = true;
        this.extendedTerm = JSON.parse(this.urlOptions.filter);
        this.filterTerm = '';
      }
      else {
        this.extendedTerm = [_.clone(this.extendedTermDefault)];
      }

      this.setUrlOptions();
    },
    
    reloadPageAfterResize() {
      this.reloadPage();
    },
    
    reloadPage : function(apiParts) {
      var self = this;
      // first close dropdown menu
      var menu = document.getElementById("dropdown-sort");
      if (menu!==null) {
        menu.classList.remove("open");
      }

      //
      flexyState.api({
        url       : self.apiUrl(apiParts),
      })
      .then(function(response){
        self.isLoading = false;
        if (!_.isUndefined(response.data)) {
          if (response.data.success) {
            // Zijn er settings meegekomen?
            if ( !_.isUndefined(response.data.settings) ) {
              // Title
              if (!_.isUndefined(response.data.settings.grid_set.title)) self.uiTitle = response.data.settings.grid_set.title;
              // Pagination
              if (!_.isUndefined(response.data.settings.grid_set.pagination)) self.pagination = response.data.settings.grid_set.pagination;
              // Fields
              self.fields = response.data.settings.grid_set.field_info;
              self.searchable_fields = response.data.settings.grid_set.searchable_fields;
              // Actions?
              if (!_.isUndefined(response.data.settings.grid_set.actions)) {
                self.actions = response.data.settings.grid_set.actions;
              }
            }
            // Data en die aanvullen met data
            var data = response.data.data;
            
            // Als data is 0 bij filter, geef een popup
            if (data.length==0 && self.apiParts.filter!=='') {
              // Vraag of filter gereset of niet
              var message = self.$lang['grid_no_result'];
              flexyState.openModal( {'title':'','body':message,'size':'modal-sm'}, function(event) {
                if ( event.state.type==='ok') {
                  self.apiParts.filter = '';
                  self.findTerm = '';
                  self.extendedFind = false;
                  return self.reloadPage(self.apiParts);
                }
              });
            }

            if (self.pagination) {
              self.calcLimit();
              data.splice(self.apiParts.limit);
            }

            self.items = self.addInfo( data, true );
            self.dataInfo = response.data.info;
          }
        }
        return response;
      });
    },
    
    apiUrl : function(parts) {
      parts = _.extend( this.apiParts, parts );
      if (!this.pagination) {
        parts.offset = 0;
        parts.limit = 0;
      }
      this.apiParts = parts;
      var url = this.api;
      if (this.gridType()==='media') {
        url += '?table=res_assets&path='+this.name;
      }
      else {
        url += '?table='+this.name + '&txt_abstract='+parts.txt_abstract + '&as_grid='+parts.as_grid;
      }
      url += '&offset='+parts.offset + '&limit='+parts.limit + '&order='+parts.order + '&filter={'+jdb.encodeURL(parts.filter)+'}';
      if (this.fields.length==0) {
        url += '&settings=grid_set';
      }
      // Options in URL query
      this.urlOptions = {
        offset : parts.offset,
        limit  : parts.limit,
        order  : parts.order,
        filter : parts.filter,
      };
      if (this.changeUrlApi) history.pushState(this.urlOptions, '', location.pathname+'?options='+JSON.stringify(this.urlOptions));
      return url;
    },
    
    hasData : function() {
      return (this.items.length>0 || this.gridType()==='media');
    },
    
    /*
      Voeg (tree)info toe aan meegegeven items
    */
    addInfo : function(items,addSchema) {
      var data     = items;
      var isTree   = this.gridType()=='tree';
      if (isTree) {
        var parents    = {};
        var level      = 0;
        var parent_key = 0;
      }
      for (var i = 0; i < data.length; i++) {
        var row = data[i];
        var id = row['id'];
        // Add info to each cell
        if (addSchema===true) {
          for (var field in row) {
            // Defaults
            if ( _.isUndefined(this.fields[field]) ) {
              this.fields[field] = [];
              this.fields[field]['type']      = 'input';
              this.fields[field]['grid-type'] = 'input';
              this.fields[field]['readonly']  = false;
            }
            else {
              if ( _.isUndefined(this.fields[field]['type']) )      this.fields[field]['type'] = 'input';
              if ( _.isUndefined(this.fields[field]['grid-type']) ) this.fields[field]['grid-type'] = 'input';
              if ( _.isUndefined(this.fields[field]['readonly']) )  this.fields[field]['readonly'] = false;
            }
            data[i][field] = {
              'type'  : this.fields[field]['grid-type'] || this.fields[field]['type'],
              'value' : row[field]
            };
            if ( this.fields[field].type==='number' && this.fields[field]['type']==='select') {
              var jsonValue = JSON.parse(row[field].value);
              data[i][field] = {
                'type'  : this.fields[field]['grid-type'] || this.fields[field]['type'],
                'value' : Object.values(jsonValue)[0],
                'id'    : Object.keys(jsonValue)[0],
              };
            }
            data[i][field].name = field;
          }
        }
        // Add tree info to each row
        if (isTree) {
          row._info = {
            level         : 0,
            is_child      : false,
            has_children  : false,
          };
          parent_key   = row.self_parent.value;
          // if not on toplevel:
          if (parent_key>0) {
            row._info.is_child=true;
            // are we on a known level?
            if ( ! _.isUndefined(parents[parent_key]) ) {
              // yes: get that level
              level = parents[parent_key];
            }
            else {
              // no: remember new level
              level++;
              parents[parent_key] = level;
            }
          }
          else {
            // on root, so level = 0
            level=0;
          }
          // add level info
          row._info.level = level;
        }
        // Keep new row
        data[i] = row;
      }
      // Add more tree info (has_children)
      if (isTree && parents!=={}) {
        _.forEach(data,function(row,key){
          var id = row.id.value;
          var level = parents[id];
          if (level) {
            data[key]._info.has_children = true;
          }
        });
      }
      // Console
      if (isTree && flexyState.debug) {
        console.log('treeInfo:');
        _.forEach(data,function(row){ console.log('id:',row.id.value,'order:',row.order.value,'self_parent:',row.self_parent.value,'level:',row._info.level,'isChild:',row._info.is_child,'hasChildren:',row._info.has_children,'title:',row.str_title.value); });
      }
      return data;
    },
    
    gridType : function() {
      var type = this.type;
      if (type==='mediapicker') {
        type = 'media';
        this.changeUrlApi = false;
      }
      if (typeof(this.fields.order)!=='undefined' && (this.apiParts.order==='' || this.apiParts.order==='order') && this.apiParts.filter==='') type='ordered';
      if (typeof(this.fields.self_parent)!=='undefined' && (this.apiParts.order==='' || this.apiParts.order==='order') && this.apiParts.filter==='') type='tree';
      return type;
    },

    gridTypeClass : function() {
      var c = 'grid-type-'+this.gridType();
      if (this.gridType()==='media') {
        c += ' grid-media-view-'+this.getMediaView();
      }
      return c;
    },
    
    needsPagination : function(){
      return (typeof(this.dataInfo.num_pages)!=='undefined' &&  this.dataInfo.num_pages > 1);
    },
    
    isPrimaryHeader : function(field) {
      var headerType = field['grid-type'] || field['type'];
      return (headerType==='primary');
    },
    isActionHeader : function(field) {
      var headerType = field['grid-type'] || field['type'];
      return (headerType==='action');
    },
    isNormalVisibleHeader : function(field) {
      var headerType = field['grid-type'] || field['type'];
      return (headerType!=='hidden' && headerType!=='primary'  && headerType!=='action');
    },
    hasFieldInfo : function(field) {
      return !_.isUndefined(this.fields[field]);
    },
    isSortableField : function(field) {
      return field.sortable;
    },

    isMediaThumbs : function() {
      return (this.gridType()==='media' && this.getMediaView()!=='list');
    },
    
    getMediaView : function() {
      return flexyState.getMediaView();
    },

    setMediaView : function(view) {
      this.calcLimit(view);
      this.reloadPageAfterResize();
      return flexyState.setMediaView(view);
    },

    headerClass : function(field) {
      var c = 'grid-header-type-'+field['type'];
      if (field['readonly']) c+=' grid-header-muted';
      return c;
    },
    
    hasSelection : function() {
      return this.selected.length>0;
    },

    oneSelected : function() {
      return this.selected.length==1;
    },
    
    isSelected : function(id) {
      return this.selected.indexOf(id) > -1;
    },
    
    select: function(id) {
      if (this.multiple===false) {
        this.selected = [];
      }
      var index = this.selected.indexOf(id);

      if (index > -1) {
        this.selected.splice(index, 1);
      }
      else {
        this.selected.push(id);
      }

      this.emitToggleMedia(id);
    },
    
    reverseSelection:function() {
      var ids = [];
      for (var i = 0; i < this.items.length; i++) {
        ids.push(this.items[i].id.value);
      }
      this.selected = _.difference(ids,this.selected);
    },
    
    emitToggleMedia : function(id) {
      if (this.type==='mediapicker') {
        var media = this.findMediaByIndex(id);
        this.$emit('grid-toggle-item',media);
        // console.log('emitToggleMedia',id,media);
      }
    },

    findMediaByIndex : function(id) {
      var media = false;
      for (var j = 0; j < this.items.length; j++) {
        var index = this.items[j]['id'].value;
        if (index===id) {
          media = this.items[j]['media_thumb'].value;
        }
      }
      return media;
    },
    
    newItem : function() {
      if (this.gridType()==='media') {
        var event = new MouseEvent('click', {
          'view': window,
          'bubbles': true,
          'cancelable': true
          });
        document.getElementById('browsefiles').dispatchEvent(event);
      }
      else {
        this.editItem(-1);
      }
    },
    
    editItem : function(id) {
      // copy?
      if (this.oneSelected()) {
        var id = '_'+this.selected[0];
      }
      var name = this.name;
      if (this.gridType()==='media') name = 'media_'+name;
      var url = '/edit/'+name+'/'+id+'?options='+JSON.stringify(this.urlOptions);
      this.$router.push(url);
    },
    
    removeItems : function(removeIds) {
      var self = this;
      if ( _.isUndefined(removeIds)) {
        removeIds = this.selected;
      }
      else {
        removeIds = [removeIds];
      }
      // Only when there are items to remove
      if (removeIds.length>0) {
        // Confirm
        var message = this.$lang['confirm_delete_one'];
        if (removeIds.length>1) message = this.$options.filters.replace( this.$lang['confirm_delete_multiple'], removeIds.length );
        
        flexyState.openModal( {'title':'','body':message,'size':'modal-sm'}, function(event) {
          if ( event.state.type==='ok') {
            var data = {
              table : self.name,
              where : removeIds,
            };
            if (self.gridType()==='media') {
              data.table = 'res_assets';
              data.path = self.name;
            }
            return flexyState.api({
              url   : 'row',
              data  : data,
            }).then(function(response){
              var error = response.error || (response.data.data===false);
              if (error) {
                flexyState.addMessage( self.$lang.error_delete, 'danger');
              }
              else {
                flexyState.addMessage( self.$options.filters.replace( self.$lang.deleted, removeIds.length));
                self.reloadPage();
              }
              return response;
            });
          }
        });
        
      }
    },
    
    actionName : function(action) {
      var action_name = '';
      if (!_.isUndefined(action.name))     action_name = action.name;
      if (!_.isUndefined(action.name_all)) action_name = action.name_all;
      if (!_.isUndefined(action.name_select) && this.hasSelection()) action_name = action.name_select;
      return action_name;
    },

    showAction : function(action) {
      var selected_only = false;
      if (!_.isUndefined(action.selected_only)) selected_only = action.selected_only;
      if (selected_only && !this.hasSelection()) return false;
      return true;
    },

    // Grid action
    startAction : function(action) {
      var self = this;
      var url = action.url;
      if (this.selected.length>0) {
        var where='';
        for (var i = 0; i < this.selected.length; i++) {
          where += '&where[]=' + this.selected[i];
        }
        if (url.indexOf('?')<0) {
          url += '?' + where.substr(1);
        }
        else {
          url += where;
        }
      }
      flexyState.api({
        method :'POST',
        url    : url,
      })
      .then(function(response){
        if (!_.isUndefined(action.reload)) {
          self.reloadPage(action.reload);
        }
        return response;
      });
    },
    
    // Row action
    action: function(action) {
      var self = this;
      return flexyState.api({
        method: 'POST',
        url : action.uri,
      }).then(function(response){
        if (!_.isUndefined(action.reload) && action.reload) {
          self.reloadPage(action.reload);
        }
        return response;
      });
    },
    actionClass : function(cell) {
      if (!_.isUndefined(cell.value.class)) return cell.value.class || 'btn-outline-warning';
      return 'btn-outline-warning';
    },
        
    rowLevel:function(row) {
      if (_.isUndefined(row._info)) return 0;
      return row._info.level;
    },
    
    isEditable : function(name) {
      var editable = false;
      if ( !_.isUndefined(this.fields[name]) ) editable = this.fields[name]['grid-edit'];
      // console.log('isEditable',name,this.fields[name],editable);
      return editable;
    },
    
    isReadonly : function(name) {
      var readonly = false;
      if ( !_.isUndefined(this.fields[name]) ) readonly = this.fields[name]['readonly'];
      return readonly;
    },
    
    startFinding : function(event) {
      if (event) event.preventDefault();
      var self = this;
      var find = '';
      if ( !self.extendedFind ) {
        find = this.findTerm.replace(/'/g,'"');
      }
      else {
        var filled = true;
        for (var i = 0; i < this.extendedTerm.length; i++) {
          if (this.extendedTerm[i].field === '') filled = false;
          if (this.extendedTerm[i].term === '') filled = false;
        }
        if (this.extendedTerm.length<1) filled = false;
        if (!filled) return false;
        find = JSON.stringify(self.extendedTerm);
      }
      this.reloadPage({offset:0,filter:find});
    },
    
    findChanged : function() {
      if (this.findTerm==='') this.stopFind();
      this.oldExtendedTerm = [];
    },
    
    stopFind : function() {
      this.findTerm = '';
      this.extendedFind = false;
      this.extendedTerm = [_.clone(this.extendedTermDefault)];
      this.reloadPage({offset:0,filter:''});
    },
    
    toggleExtendedFind : function() {
      if (this.extendedFind) {
        this.extendedFind = false;
        this.findTerm = '';
        if (!_.isUndefined(this.extendedTerm[0])) {
          this.findTerm = this.extendedTerm[0].term;
          this.oldExtendedTerm = this.extendedTerm;
        }
      }
      else {
        this.extendedFind = true;
        if (this.oldExtendedTerm.length>0) {
          this.extendedTerm = this.oldExtendedTerm;
        }
        else {
          this.extendedTerm = [_.clone(this.extendedTermDefault)];
          this.extendedTerm[0].term = this.findTerm;
          this.extendedTerm[0].field = this.searchable_fields[0];
        }
      }
      this.startFinding();
    },
    
    extendedSearchAdd : function() {
      this.extendedTerm.push( _.clone(this.extendedTermDefault) );
    },
    extendedSearchRemove : function(index) {
      this.extendedTerm.splice(index,1);
      if (this.extendedTerm.length<1) this.extendedTerm = [_.clone(this.extendedTermDefault)];
    },
    
    dropUploadFiles : function(event) {
      event.stopPropagation();
      event.preventDefault();
      var files = event.target.files || event.dataTransfer.files;
      this._addUploadFiles(files);
    },
    addUploadFiles : function(event) {
      var files = event.target.files || event.dataTransfer.files;
      this._addUploadFiles(files);
    },
    removeUploadFile : function(index) {
      this.uploadFiles.splice(index,1);
    },
    _addUploadFiles : function(files) {
      for (var i = 0; i < files.length; i++) {
        this.uploadFiles.push( files.item(i) );
      }
      if (files.length>0) {
        this.startUpload();
      }
    },
    startUpload : function() {
      var self = this;
      self.dropUploadHover = false;

      // Test of ze te groot zijn
      for (var i = 0; i < self.uploadFiles.length; i++) {
        if ( self.uploadFiles[i].size > flexyState.getState('max_uploadsize') ) {
          flexyState.addMessage( self.uploadFiles[i].name + self.$lang.upload_too_big, 'danger' );
          self.removeUploadFile(i);
        }
      }

      // Upload
      if (self.uploadFiles.length>0) {
        var uploadedFilesCount = 0;
        for (var i = 0; i < self.uploadFiles.length; i++) {
          var file = self.uploadFiles[i];
          var formData = new FormData();
          formData.append( 'path', self.name );
          formData.append( 'file', self.uploadFiles[i] );
          formData.append( 'fileName', self.uploadFiles[i].name );
          // Voor de zekerheid... soms geeft het anders problemen...
          formData.append( 'Authorization', _flexy.auth_token );
          formData.append( '_authorization', _flexy.auth_token );

          flexyState.api({
            method    : 'POST',
            url       : 'media',
            data      : formData,
            formData  : true,
          }).then(function(response){
            var error = '';

            if ( _.isUndefined(response.data) || _.isUndefined(response.data.data) ) {
              error = self.$lang.upload_error;
            }
            else {
              error = response.data.error;
              if (error) {
                flexyState.addMessage( error, 'danger' );
              }
              else {
                uploadedFilesCount++;
                var fileName = response.data.data.file;
                if ( !_.isUndefined(response.data.data.orig_name) ) {
                  var origName = response.data.data.orig_name;
                  if (origName !== fileName && response.data.message.indexOf('text-danger')>0 ) { // LET op
                    flexyState.addMessage( response.data.message, 'danger' );  
                  }
                  if (self.type==='mediapicker') {
                    self.$emit('grid-uploaded-item',fileName);
                  }
                }

                // Uit de lijst halen
                var index = jdb.indexOfProperty(self.uploadFiles,'name',fileName);
                self.removeUploadFile(index);
              }
            }

            // Als alles uit de lijst is geuploade, reload
            if (self.uploadFiles.length === 0 ) {
              flexyState.addMessage(uploadedFilesCount + self.$lang.upload_count);
              self.reloadPage();
            }
            return response;
          });
        }
      }
      
    },

    /**
     * Bulkupload methods
     */
    bulkUpload : function() {
      var self = this;
      if (!_.isUndefined(this.dataInfo.bulkupload)) {
        self.bulkuploadFiles = this.dataInfo.bulkupload;
        var file = '';
        for (var i = self.bulkuploadFiles.length - 1; i >= 0; i--) {
          file = self.bulkuploadFiles[i];
          flexyState.api({
            url : 'media?action=bulkupload&path='+this.name+'&file='+file,
          })
          .then(function(response){
            if (!_.isUndefined(response.data.data)) {
              self.bulkuploadFiles = _.without(self.bulkuploadFiles, response.data.args.file);
              flexyState.addMessage(response.data.args.file + self.$lang.upload_ready);
              if (self.bulkuploadFiles.length==0) {
                self.reloadPage();
              }
            }
          });
        }
      }
    },
    hasBulkupload : function() {
      if (!_.isUndefined(this.dataInfo.bulkupload)) {
        return this.dataInfo.bulkupload.length > 0;
      }
      return false;
    },
    bulkUploadTitle : function() {
      if (!_.isUndefined(this.dataInfo.bulkupload)) {
        return this.dataInfo.bulkupload.length + this.$lang.files_for_bulkupload;
      }
      return '';
    },


    /**
     * Dragging methods
     */
    isHiddenChild : function(id) {
      if (this.draggable.children===false) return false;
      return this.draggable.children.indexOf(id) >= 0;
    },
    isDragging : function(id) {
      return this.draggable.item == id;
    },
    draggable_onStart: function(event){
      var index = event.oldIndex;
      // Onthoud 'id' van draggable item
      this.draggable.item = event.item.dataset.id;
      // Onthoud 'order' van eerste item
      this.draggable.orderStart = this.items[0]['order'].value;
      // Onthoud kopie van huidige items
      this.draggable.oldItems = _.cloneDeep(this.items);
      // Als tree, onthoud dan de children als die er zijn
      this.draggable.children = false;
      if (this.gridType()==='tree' && this.items[index]._info.has_children) {
        this.draggable.children = [];
        var row = this.items[index]._info;
        var childIndex = index;
        var node_level=0;
        do {
          childIndex++;
          if ( !_.isUndefined(this.items[childIndex]) ) {
            node_level = this.items[childIndex]._info.level;
            if (node_level>row.level) this.draggable.children.push(this.items[childIndex].id.value);
          }
        } while (node_level>row.level && !_.isUndefined(this.items[childIndex]));
      }
    },
    draggable_onMove : function(event) {
      this.dragPosition = '';
      // console.log('draggable_onMove',event);
      var rect = event.draggedRect;
      if (event.relatedRect.top <= rect.top) this.dragPosition = 'top';
      if (event.relatedRect.top+event.relatedRect.height >= rect.bottom) this.dragPosition = 'bottom';
      // if (this.dragPosition!=='') {
      //   console.log('draggable_onMove',this.dragPosition, event.relatedRect.top);
      //   this.mouseInterval = setInterval(function(){
      //     if (this.mouseY < event.relatedRect.top) this.dragPosition = 'PREV';
      //     if (this.mouseY > (event.relatedRect.top+event.relatedRect.height) ) this.dragPosition = 'NEXT';
      //     console.log(this.dragPosition);
      //   },100);
      // }
      // else {
      //   clearInterval(this.mouseInterval);
      // }
    },
    draggable_onEnd  : function(event){
      var self = this;
      var oldIndex = event.oldIndex;
      var newIndex = event.newIndex;
      if (_.isUndefined(newIndex)) newIndex = oldIndex;

      if (oldIndex!==newIndex) {
        this.draggable.oldIndex = oldIndex;
        this.draggable.newIndex = newIndex;
        
        var items = _.cloneDeep(this.draggable.oldItems);
        var number_of_children = 0;
        var parent = 0; 
        if (this.gridType()==='tree') {
          number_of_children = this.draggable.children.length || 0;
          // Pas parent van verplaatste item aan
          // Bijna altijd 0, behalve als het volgende item een hoger level heeft: dan heeft het dezelfde parent als dat item, dus als er een item na komt, neem die parent.
          var next = newIndex;
          if (newIndex>oldIndex) {
            next++;
          }
          if ( next < self.dataInfo.num_rows-1 ) {
            if ( !_.isUndefined( items[next] ) ) {
              var nextItem = _.cloneDeep( items[next] );
              parent = nextItem.self_parent.value;
            }
          }
          items[oldIndex].self_parent.value = parent;
        }
        // console.log(oldIndex,newIndex,next,number_of_children);

        // Verplaats item & children
        if (number_of_children>0 && newIndex>oldIndex) {
          items = jdb.moveMultipleArrayItems( items, oldIndex, number_of_children + 1, newIndex - number_of_children);
        } 
        else {
          items = jdb.moveMultipleArrayItems( items, oldIndex, number_of_children + 1, newIndex);
        }
        
        // Update 'order'
        var order = this.draggable.orderStart;
        for (var i = 0; i < items.length; i++) {
          items[i].order.value = order;
          order++;
        }
        // Vernieuw de tree info
        this.items = _.cloneDeep(items);
        if (this.gridType()=='tree') this.items = this.addInfo(this.items);
        
        if (flexyState.debug) {
          console.log( 'draggable_onEnd ---------' );
          console.log(oldIndex,' => ',newIndex);
          self._log(self.items);
        }
        
        var newOrder = this.draggable.orderStart + this.items[ this.draggable.newIndex ].order.value;
        // console.log(newOrder);
        if (self.draggable.children && newIndex>oldIndex) newOrder = newOrder - self.draggable.children.length;
        self.postNewOrder( newOrder ).then(function(response){
          self.draggable.item = false;
        });
      }
      else {
        self.draggable.item = false;
      }
      
      // Laat children weer zien
      this.draggable.children = false;
    },

    postNewOrder : function(newOrder) {
      var self=this;
      var itemId = this.draggable.item;
      // var newOrder = this.draggable.orderStart + this.items[ this.draggable.newIndex ].order.value;
      return flexyState.api({
        method: 'POST',
        url : 'table_order',
        'data': {
          'table' : self.name,
          'id'    : itemId,
          'from'  : newOrder,
        },
      }).then(function(response){
        var error = response.error;
        if (!error && response.data.data===false) error = true;
        if (error) {
          flexyState.addMessage( self.$lang.grid_order_save_error, 'danger');
          // Bij fout: Terug naar oude situatie
          self.items = self.draggable.oldItems;
        }
        return response;
      });
    },
    
    
    _log : function( items ) {
      var self = this;
      _.forEach(items,function(row){
        if (self.gridType()==='tree') {
          console.log( row.id.value, row.order.value, 'tree:', row._info.level, row._info.is_child,row._info.has_children, row.str_title.value);
        }
        else {
          console.log( row.id.value, row.order.value, row.str_title.value);
        }
      });
    }
    
  }
}
</script>

<template>
  <div>
    
    <div class="card grid" :class="gridTypeClass()" @dragover.prevent  @drop="dropUploadFiles" @dragover="dropUploadHover=true" @dragenter="dropUploadHover=true" @dragleave="dropUploadHover=false" @dragend="dropUploadHover=false">
      <!-- MAIN HEADER -->
      <div class="card-header">
        <h1>{{uiTitle}}</h1>

        <!-- ACTIONS ?-->
        <div v-if="actions.length>0" class="grid-actions">
          <div v-for="action in actions" class="grid-action">
            <flexy-button @click.native="startAction(action)" :icon="action.icon" :text="actionName(action)" class="btn-default text-primary" :class="action.class" />
          </div>
        </div>
        
        <!-- FAST SEARCH -->
        <form class="form-inline" @submit="startFinding($event)">
          <div class="form-group" v-if="!extendedFind">
            <input type="text" v-model.trim="findTerm" class="form-control form-control-sm" id="grid-find" :placeholder="$lang.grid_fast_search" @input="findChanged()">
          </div>
          <div class="btn-group">
            <flexy-button @click.native.stop.prevent="startFinding($event)" icon="search" class="btn-default" />
            <flexy-button @click.native.stop.prevent="stopFind()" icon="refresh" class="btn-default text-danger" v-if="findTerm!=='' || extendedFind" />
            <flexy-button @click.native.stop.prevent="toggleExtendedFind()" :icon="{'chevron-down':!extendedFind,'chevron-up':extendedFind}" class="btn-default text-primary" />
          </div>
        </form>
      </div>

      <!-- EXTENDED SEARCH -->
      <div class="card-header grid-extended-find" v-if="extendedFind">
        <h4>{{$lang.grid_extended_search}}</h4>
        <form v-for="(term,index) in extendedTerm" class="form-inline" @submit.stop.prevent="startFinding($event)" :index="index">
          <div class="form-group grid-extended-search-and">
            <select class="form-control form-control-sm custom-select" name="grid-extended-search-and[]" v-model="term.and">
              <option value="OR" :selected="term.and=='OR'">{{$lang.grid_search_or}}</option>
              <option value="AND" :selected="term.and=='AND'">{{$lang.grid_search_and}}</option>
            </select>
          </div>
          <div class="form-group grid-extended-search-field">
            <select class="form-control form-control-sm custom-select" name="grid-extended-search-field[]" v-model="term.field">
              <option v-if="hasFieldInfo(field)" v-for="field in searchable_fields" :value="field" :selected="term.field===field">{{fields[field].label}}</option>
            </select>
          </div>
          <div class="form-group grid-extended-search-equals">
            <select class="form-control form-control-sm custom-select" name="grid-extended-search-equals[]" v-model="term.equals">
              <option value="exist" :selected="term.equals==='exist'">{{$lang.grid_search_exist}}</option>
              <option value="word" :selected="term.equals==='word'">{{$lang.grid_search_word}}</option>
              <option value="exact" :selected="term.equals==='exact'">{{$lang.grid_search_exact}}</option>
            </select>
          </div>
          <div class="form-group grid-extended-search-term">
            <input type="text" class="form-control form-control-sm" v-model="term.term" :placeholder="$lang.grid_search" name="grid-extended-search-term[]">
          </div>
          <flexy-button @click.native.stop.prevent="extendedSearchRemove(index)" icon="remove" class="btn-outline-danger" />
          <flexy-button @click.native.stop.prevent="extendedSearchAdd()" icon="plus" class="btn-outline-warning" />
        </form>
      </div>

      <!-- GRID HEADERS -->
      <div class="card-body table-responsive">
        <table class="table table-bordered table-sm grid-data">
          <thead>
            <tr>
              <template v-for="(field,key) in fields">
                
                <th v-if="isPrimaryHeader(field)" :class="headerClass(field)" class="text-primary grid-actions">
                  <flexy-button v-if="dataInfo.rights.insert==true" @click.native="newItem()" :icon="{'plus':!oneSelected(),'paste':oneSelected()}" class="btn-outline-warning" />
                  <flexy-button v-if="type!=='mediapicker' && dataInfo.rights.delete==true" @click.native="removeItems()" icon="remove" :class="{disabled:!hasSelection()}" class="btn-outline-danger action-delete-all" />
                  <flexy-button v-if="type!=='mediapicker' && multiple===true && dataInfo.rights.delete==true" @click.native="reverseSelection()" icon="check-square-o" class="btn-outline-info action-select-all" />

                  <div v-if="isMediaThumbs()" class="dropdown" id="dropdown-sort">
                    <flexy-button icon="sort-amount-asc" class="btn-outline-info" dropdown="dropdown-sort" />
                    <div class="dropdown-menu">
                      <a v-for="(field,key) in fields" v-if="isSortableField(field)" @click="reloadPage({'order':(key==apiParts.order?'_'+key:key)})" class="dropdown-item" :class="{'selected':(apiParts.order.indexOf(key)>=0)}">
                        <span v-if="apiParts.order==key" class="fa fa-caret-up"></span>
                        <span v-if="apiParts.order=='_'+key" class="fa fa-caret-down"></span>
                        {{field.label}}
                      </a>
                    </div>
                  </div>
                </th>

                <th v-if="isActionHeader(field)" :class="headerClass(field)">
                  <flexy-button v-if="field.action" v-show="showAction(field.action)" @click.native="startAction(field.action)" :icon="field.action.icon" :text="actionName(field.action)" class="btn-outline-warning" :class="field.action.class" />
                </th>

                <th v-if="isNormalVisibleHeader(field)" :class="headerClass(field)"  class="text-primary">
                  <a @click="reloadPage({'order':(key==apiParts.order?'_'+key:key)})"><span>{{field.label}}</span>
                    <span v-if="apiParts.order==key" class="fa fa-caret-up"></span>
                    <span v-if="apiParts.order=='_'+key" class="fa fa-caret-down"></span>
                  </a>
                </th>
                
              </template>
            </tr>
          </thead>
        
          <!-- GRID BODY -->
          <draggable v-if="hasData()" :list="items" tag="tbody" v-bind="draggableOptions" @start="draggable_onStart" @end="draggable_onEnd" :move="draggable_onMove">

            <!-- UPLOAD ROW -->
            <tr v-if="gridType()==='media'" class="grid-upload" :class="{'dropping':dropUploadHover}">
              <td v-if="bulkuploadFiles==false" colspan="100" class="grid-upload-dropbox">
                <span v-if="uploadFiles.length>0" :class="{'show':uploadFiles.length>0}" class="upload-spinner fa fa-spinner fa-pulse fa-fw"></span>
                <template v-if="hasBulkupload()">
                  <flexy-button v-if="hasBulkupload()" @click.native="bulkUpload()" icon="upload" class="btn-outline-danger action-bulkupload" :title="bulkUploadTitle()" />
                  {{bulkUploadTitle()}}
                </template>
                <template v-else>
                  {{$lang.upload_choose}}
                </template>
                <input id="browsefiles" @change="addUploadFiles"  type="file" name="files[]" multiple="multiple">
              </td>
            </tr>
            <!-- BULKUPLOAD ROWS -->
            <tr v-if="bulkuploadFiles!==false" v-for="file in bulkuploadFiles" class="grid-upload">
              <td><span class="upload-spinner fa fa-spinner fa-pulse fa-fw"></span></td>
              <td colspan="100">{{file}}</td>
            </tr>

            <!-- ROW -->
            <template v-for="row in items">
              <tr v-if="row" :data-id="row.id.value" :class="{'table-warning is-selected':isSelected(row.id.value)}" v-show="!isHiddenChild(row.id.value)" :level="rowLevel(row)" :key="row.id.value">
                <template v-for="cell in row">
                
                  <!-- PRIMARY CELL -->
                  <td v-if="cell.type=='primary'" class="action">
                    <flexy-button @click.native="editItem(cell.value)" icon="pencil" class="btn-outline-warning action-edit" />
                    <flexy-button v-if="type!=='mediapicker'" @click.native="removeItems(row.id.value)" icon="remove" class="btn-outline-danger action-remove" />
                    <flexy-button @click.native="select(row.id.value)" :icon="{'square-o':!isSelected(row.id.value),'check-square-o':isSelected(row.id.value)}" class="btn-outline-info action-select" />
                    <flexy-button v-if="gridType()==='tree' || gridType()==='ordered'" icon="arrows-v" class="draggable-handle btn-outline-info action-drag" :class="{'active':isDragging(row.id.value)}" />
                  </td>
                
                  <!-- ACTION CELL -->
                  <td v-else-if="cell.type=='action'" class="action">
                    <flexy-button :icon="cell.value.icon" :class="actionClass(cell)" :text="cell.value.text" @click.native="action(cell.value)" />
                  </td>
                
                  <!-- CELL -->
                  <flexy-grid-cell v-else
                    @select="select(row.id.value)"
                    :focus="false"
                    :type="cell.type"
                    :name="cell.name"
                    :value="cell.value"
                    :level="rowLevel(row)"
                    :primary="{ table:dataName(), id:row.id.value }"
                    :editable="isEditable(cell.name)"
                    :readonly="isReadonly(cell.name)"
                    :options="fields[cell.name]">
                  </flexy-grid-cell>
                
                </template>
              </tr>
            </template>
          </draggable>
        </table>
      </div>
      <!-- FOOTER -->
      <div class="card-footer text-muted">
        <div class="btn-group actions" v-if="gridType() === 'media'">
          <flexy-button @click.native="setMediaView('list')"   icon="bars"       :class="{'btn-outline-primary':getMediaView()!=='list','btn-primary':getMediaView()==='list'}" border="true" />
          <flexy-button @click.native="setMediaView('small')"  icon="th"         :class="{'btn-outline-primary':getMediaView()!=='small','btn-primary':getMediaView()==='small'}" border="true" />
          <flexy-button @click.native="setMediaView('thumbs')" icon="picture-o"  :class="{'btn-outline-primary':getMediaView()!=='thumbs','btn-primary':getMediaView()==='thumbs'}" border="true" />
        </div>
        <flexy-pagination v-if="needsPagination()" :total="dataInfo.total_rows" :maxtotal="dataInfo.count_all" :pages="dataInfo.num_pages" :current="dataInfo.page + 1" :limit="dataInfo.limit" @newpage="reloadPage({offset:$event})"></flexy-pagination>
        <div v-if="!needsPagination()" class="pagination-container">
          <span class="pagination-info text-primary">{{$lang.grid_total | replace(dataInfo.total_rows)}}</span>
        </div>
      </div>
    
    </div>
    
  </div>

</template>
